<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';require_once __DIR__ . '/../includes/auth.php';
$user=current_user();if(!$user||!in_array($user['role'],['Administrator','Head'],true)){http_response_code(403);exit('Access denied.');}if($_SERVER['REQUEST_METHOD']!=='POST'||!verify_csrf()){http_response_code(419);exit('This form has expired.');}
$id=filter_var($_POST['activity_id']??null,FILTER_VALIDATE_INT);$name=trim((string)($_POST['activity_name']??''));$category=(string)($_POST['category']??'');$description=trim((string)($_POST['description']??''));$year=filter_var($_POST['academic_year']??null,FILTER_VALIDATE_INT);$patronRaw=trim((string)($_POST['patron_id']??''));$patron=$patronRaw===''?null:filter_var($patronRaw,FILTER_VALIDATE_INT);$capRaw=trim((string)($_POST['capacity']??''));$capacity=$capRaw===''?null:filter_var($capRaw,FILTER_VALIDATE_INT);$status=(string)($_POST['status']??'Active');
if($id===false||$patron===false||$capacity===false||$name===''||strlen($name)>140||strlen($description)>1000||!in_array($category,['Sport','Club','Academic','Culture','Service','Other'],true)||!$year||$year<2000||$year>2100||($capacity!==null&&($capacity<1||$capacity>5000))||!in_array($status,['Active','Closed'],true)){$_SESSION['error']='Check the activity name, category, academic year and optional capacity.';header('Location: ../?page=activities');exit;}
$pdo=db();try{$pdo->beginTransaction();if($patron){$q=$pdo->prepare("SELECT id FROM users WHERE id=:id AND active=1 AND role IN ('Administrator','Head','Teacher') FOR UPDATE");$q->execute(['id'=>$patron]);if(!$q->fetch())throw new DomainException('Choose an active teacher or school leader as the activity patron.');}if($id){$q=$pdo->prepare('SELECT id FROM school_activities WHERE id=:id FOR UPDATE');$q->execute(['id'=>$id]);if(!$q->fetch())throw new DomainException('Activity not found.');$q=$pdo->prepare("SELECT COUNT(*) FROM activity_memberships WHERE activity_id=:id AND status='Active'");$q->execute(['id'=>$id]);if($capacity!==null&&(int)$q->fetchColumn()>$capacity)throw new DomainException('Capacity cannot be less than the current membership.');$q=$pdo->prepare('UPDATE school_activities SET activity_name=:name,category=:category,description=:description,academic_year=:year,patron_id=:patron,capacity=:capacity,status=:status WHERE id=:id');$q->execute(['name'=>$name,'category'=>$category,'description'=>$description?:null,'year'=>$year,'patron'=>$patron,'capacity'=>$capacity,'status'=>$status,'id'=>$id]);audit_log('activity.updated','school_activities',(int)$id,['category'=>$category,'academic_year'=>$year,'status'=>$status]);}else{$q=$pdo->prepare('INSERT INTO school_activities(activity_name,category,description,academic_year,patron_id,capacity,status,created_by) VALUES(:name,:category,:description,:year,:patron,:capacity,:status,:user)');$q->execute(['name'=>$name,'category'=>$category,'description'=>$description?:null,'year'=>$year,'patron'=>$patron,'capacity'=>$capacity,'status'=>$status,'user'=>$user['id']]);$id=(int)$pdo->lastInsertId();audit_log('activity.created','school_activities',$id,['category'=>$category,'academic_year'=>$year]);}$pdo->commit();$_SESSION['notice']='School activity saved.';}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('Activity save failed: '.$e->getMessage());$_SESSION['error']=$e instanceof DomainException?$e->getMessage():($e instanceof PDOException&&$e->getCode()==='23000'?'That activity already exists for this academic year.':'Could not save the activity.');}header('Location: ../?page=activities');exit;
